-- PostgreSQL storage for the preserved RBAC application. No seed data.
CREATE TABLE IF NOT EXISTS family(family_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,family_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS genus(genus_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,family_id INTEGER REFERENCES family(family_id),genus_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conservation_status(status_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,status_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS species(species_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,scientific_name TEXT NOT NULL,common_name TEXT,genus_id INTEGER REFERENCES genus(genus_id),status_id INTEGER REFERENCES conservation_status(status_id),description TEXT,rbac_data JSONB NOT NULL DEFAULT '{}'::jsonb,registered_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rbac_species_visibility(species_id INTEGER PRIMARY KEY REFERENCES species(species_id) ON DELETE CASCADE,visibility TEXT NOT NULL CHECK(visibility IN ('public','internal','protected')));
CREATE TABLE IF NOT EXISTS plant_record(plant_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,species_id INTEGER NOT NULL REFERENCES species(species_id),registered_subject TEXT NOT NULL,rbac_status TEXT NOT NULL DEFAULT 'Pending Review' CHECK(rbac_status IN ('Pending Review','Approved','Rejected','Flagged','Correction Required')),qr_token TEXT NOT NULL UNIQUE,registered_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plant_location(location_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plant_id INTEGER NOT NULL REFERENCES plant_record(plant_id),latitude DOUBLE PRECISION NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude DOUBLE PRECISION NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy_m DOUBLE PRECISION CHECK(accuracy_m>=0),recorded_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plant_observation(id TEXT PRIMARY KEY NOT NULL,plant_id INTEGER NOT NULL REFERENCES plant_record(plant_id),owner_subject TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Draft','Pending Review','Approved','Rejected','Flagged','Correction Required')),content JSONB NOT NULL,revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),client_key TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(owner_subject,client_key));
CREATE TABLE IF NOT EXISTS observation_review(id TEXT PRIMARY KEY NOT NULL,observation_id TEXT NOT NULL REFERENCES plant_observation(id),reviewer_subject TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('Approved','Rejected','Flagged','Correction Required')),comment TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plant_asset(id TEXT PRIMARY KEY NOT NULL,species_id INTEGER REFERENCES species(species_id),plant_id INTEGER REFERENCES plant_record(plant_id),owner_subject TEXT NOT NULL,client_key TEXT NOT NULL,observation_id TEXT REFERENCES plant_observation(id),approved BOOLEAN NOT NULL DEFAULT FALSE,content_type TEXT NOT NULL,content BYTEA NOT NULL CHECK(octet_length(content)<=4194304),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(owner_subject,client_key),CHECK((species_id IS NULL)!=(plant_id IS NULL)));
CREATE TABLE IF NOT EXISTS iot_device(id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,plant_id INTEGER REFERENCES plant_record(plant_id),key_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Inactive')),thresholds JSONB NOT NULL DEFAULT '{}'::jsonb,last_seen TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS sensor_reading(id TEXT PRIMARY KEY NOT NULL,device_id TEXT NOT NULL REFERENCES iot_device(id),"values" JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS threat_alert_history(id TEXT PRIMARY KEY NOT NULL,device_id TEXT NOT NULL REFERENCES iot_device(id),reading_id TEXT NOT NULL REFERENCES sensor_reading(id),metric TEXT NOT NULL,value DOUBLE PRECISION NOT NULL,status TEXT NOT NULL DEFAULT 'New' CHECK(status IN ('New','Reviewing','Resolved')),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS threat_response(id TEXT PRIMARY KEY NOT NULL,alert_id TEXT NOT NULL REFERENCES threat_alert_history(id),officer_subject TEXT NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Reviewing','Resolved')),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_audit(id TEXT PRIMARY KEY NOT NULL,actor_subject TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS observation_owner_idx ON plant_observation(owner_subject);
CREATE INDEX IF NOT EXISTS reading_device_time_idx ON sensor_reading(device_id,created_at DESC);
CREATE INDEX IF NOT EXISTS location_plant_idx ON plant_location(plant_id,recorded_at DESC);
CREATE INDEX IF NOT EXISTS observation_plant_idx ON plant_observation(plant_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS iot_ingestion_receipt(device_id TEXT NOT NULL REFERENCES iot_device(id),client_key TEXT NOT NULL,reading_id TEXT NOT NULL REFERENCES sensor_reading(id),PRIMARY KEY(device_id,client_key));
